									print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$AllFullframes$FullFrames$Side" + which_side + "$SelectGraphics$BowlingCardGfx$BowlingCard$"
											+ "Performer$PlayerImageOut$PlayerImageAll$img_PlayerImage*TEXTURE*IMAGE SET " + "\\\\\\\\"+config.getPrimaryIpAddress()+"\\\\"+local_photo_path + inn.getBowling_team().getTeamName4().toUpperCase() + 
											"\\\\" + boc.getPlayer().getPhoto() + CricketUtil.PNG_EXTENSION + " \0");
									print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$AllFullframes$FullFrames$Side" + which_side + "$SelectGraphics$BowlingCardGfx$BowlingCard$"
											+ "Performer$PlayerImageOut$PlayerImageAll$img_PlayerShadow*TEXTURE*IMAGE SET " + "\\\\\\\\"+config.getPrimaryIpAddress()+"\\\\"+local_photo_path + inn.getBowling_team().getTeamName4().toUpperCase() + 
											"\\\\" + boc.getPlayer().getPhoto() + CricketUtil.PNG_EXTENSION + " \0");
