							print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$AllFullframes$FullFrames$Side" + whichside + "$SelectGraphics$BowlingCardGfx$BowlingCard$Normal$"
									+ "FowGrp$Fow3*ACTIVE SET 0 \0");
							//TimeUnit.MILLISECONDS.sleep(2);
