	public void populateBug(PrintWriter print_writer,String viz_scene, int whichInning, String statsType, int playerId, MatchAllData match, String broadcaster) throws InterruptedException
	{
		if (match == null) {
			System.out.println("ERROR: populateBug -> Match is null");
		} else if (match.getMatch().getInning() == null) {
			System.out.println("ERROR: populateBug -> inning is null");
		} else {
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$LINES$1Line$SelectStatValue*FUNCTION*Omo*vis_con SET 1 \0");
			
			for(Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					switch(statsType.toUpperCase()) {
					case CricketUtil.BATSMAN :
						for (BattingCard bc : inn.getBattingCard()) {
							if(bc.getPlayerId()==playerId) {
								if(bc.getStatus().toUpperCase().equalsIgnoreCase(CricketUtil.NOT_OUT)) {
									print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$LINES$1Line$SelectStatValue$RightGrp$StatHeadHrp$MaxSize$txt_StatValue*GEOM*TEXT SET " +
											bc.getRuns() +"* "+ "(" + bc.getBalls() + ")" + "\0");
								}else {
									print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$LINES$1Line$SelectStatValue$RightGrp$StatHeadHrp$MaxSize$txt_StatValue*GEOM*TEXT SET " +
											bc.getRuns() + "(" + bc.getBalls() + ")" + "\0");
								}
								
								print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$LINES$1Line$SubHeaderGrp$SubHeaderText$txt_StatHead1*GEOM*TEXT SET " +
										bc.getPlayer().getTicker_name() + "\0");
								
								print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$LINES$1Line$SubHeaderGrp$SubHeaderText$Txt_StatHead2*GEOM*TEXT SET " +
										"4s : " + bc.getFours() + " 6s : " + bc.getSixes() + "\0");
								
							}
						}
						break;
					}
				}
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.040 \0");
			TimeUnit.MILLISECONDS.sleep(200);	
		}
	}	
