					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$AllFullframes$Side1$SelectGraphics$LineUpBothGfx$LineUpBoth$AllGroup$MainData$HomeTeamGoup$TeamGroupAll$"
							+ "Out$RowAnim$LogoMotion$img_TeamBadges*TEXTURE*IMAGE SET " + logo_path +	match.getSetup().getHomeTeam().getTeamName4() + "\0");
					
