						print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Grp$PositionY$All$HomeLogoGrp$LogoMasked$TeamColour*TEXTURE*IMAGE SET "+ team_color + match.getSetup().getHomeTeam().getTeamName3().toLowerCase() + " \0");
